import type { APIRoute } from "astro";

// robots.txt (and agent-readiness scanners) point at /sitemap.xml. Serve it as a
// sitemap index that points to the page sitemap generated by @astrojs/sitemap,
// so the advertised sitemap can never drift from the pages that actually exist.
export const GET: APIRoute = ({ site }) => {
  const pageSitemap = new URL("/sitemap-0.xml", site ?? "https://cadencelab.co")
    .href;

  const body = [
    '<?xml version="1.0" encoding="UTF-8"?>',
    '<sitemapindex xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">',
    `<sitemap><loc>${pageSitemap}</loc></sitemap>`,
    "</sitemapindex>",
  ].join("");

  return new Response(body, {
    headers: { "Content-Type": "application/xml; charset=utf-8" },
  });
};
